def solve(rolls, spaces):
    """
    Calculate probability of reaching exactly the final space (spaces) 
    starting from position 1, with given number of rolls.
    """
    from fractions import Fraction

    # Memoization: (current_position, rolls_remaining) -> probability of winning
    memo = {}

    def win_probability(position, rolls_left):
        if position == spaces:
            return Fraction(1)  # Already won
        if position > spaces:
            return Fraction(0)  # Overshot, lost
        if rolls_left == 0:
            return Fraction(0)  # Out of rolls, didn't win

        if (position, rolls_left) in memo:
            return memo[(position, rolls_left)]

        prob = Fraction(0)

        # Try each dice outcome (1-6)
        for dice in range(1, 7):
            new_position = position + dice

            # Check if we land on exactly the final space
            if new_position == spaces:
                prob += Fraction(1, 6) * Fraction(1)
            elif new_position < spaces:
                # Continue with remaining rolls
                prob += Fraction(1, 6) * win_probability(new_position, rolls_left - 1)
            # else: overshot, contributes 0

        memo[(position, rolls_left)] = prob
        return prob

    result = win_probability(1, rolls)
    return float(result)

