    return math.ceil(num_pages / pages_per_day)

result = solve(274, 20)
print(result)

def solve(item_price, num_items, discount_percentage):
    original_total = item_price * num_items

    # Apply discount only if more than 3 items
    if num_items > 3:
        discounted_total = original_total * (1 - discount_percentage / 100)
    else:
        discounted_total = original_total

    return discounted_total

result = solve(100, 5, 20)
print(result)  # 400.0

def solve(hours, rate):
    base_cost = hours * rate
    if base_cost > 100:
        final_cost = base_cost * 0.9  # Apply 10% discount
    else:
        final_cost = base_cost
    return final_cost

# Call with the given values
result = solve(20, 50)
print(result)
